const listPublicTournamentReadSeries = `-- name: ListPublicTournamentReadSeries :many
SELECT series.id AS series_id,
    COALESCE(series_stage.stage, 'golden')::TEXT AS stage,
    COALESCE(series_stage.round_number, 0)::SMALLINT AS round_number,
    series.format,
    series.state,
    first_player.username AS first_display_name,
    second_player.username AS second_display_name,
    series.first_participant_wins,
    series.second_participant_wins,
    COALESCE(current_game.current_game_position, 0)::INTEGER AS current_game_position,
    COALESCE(current_game.current_game_category, '')::TEXT AS current_game_category,
    COALESCE(current_game.current_game_state, '')::TEXT AS current_game_state,
    current_game.current_game_started_at,
    current_game.current_game_effective_deadline,
    current_game.current_game_finished_at,
    current_game_solve.submission_received_at AS current_game_solve_submission_received_at,
    COALESCE(current_game.current_game_result_reason, '')::TEXT AS current_game_result_reason,
    current_game.current_game_winner_display_name,
    COALESCE(current_game.first_connection_status, 'unknown')::TEXT AS first_connection_status,
    COALESCE(current_game.second_connection_status, 'unknown')::TEXT AS second_connection_status,
    NULL::TIMESTAMPTZ AS scheduled_at
FROM series
JOIN participants AS first_participant
    ON first_participant.id = series.first_participant_id
JOIN players AS first_player ON first_player.id = first_participant.player_id
JOIN participants AS second_participant
    ON second_participant.id = series.second_participant_id
JOIN players AS second_player ON second_player.id = second_participant.player_id
LEFT JOIN LATERAL (
    SELECT stage.stage,
        stage.round_number
    FROM (
        SELECT 'swiss'::TEXT AS stage,
            swiss_round.round_number::SMALLINT AS round_number,
            2 AS stage_rank,
            swiss_round.updated_at AS evidence_at,
            swiss_round.id AS evidence_id
        FROM wave_series AS linked_series
        JOIN swiss_wave_links AS swiss_link
            ON swiss_link.wave_id = linked_series.wave_id
            AND swiss_link.tournament_id = linked_series.tournament_id
            AND swiss_link.roster_id = linked_series.roster_id
        JOIN swiss_rounds AS swiss_round
            ON swiss_round.id = swiss_link.round_id
            AND swiss_round.roster_id = swiss_link.roster_id
        WHERE linked_series.series_id = series.id
            AND linked_series.tournament_id = series.tournament_id
            AND linked_series.roster_id = series.roster_id

        UNION ALL

        SELECT 'semifinal'::TEXT,
            NULL::SMALLINT,
            1,
            semifinal.created_at,
            semifinal.command_id
        FROM tournament_stage_playoff_semifinals AS semifinal
        WHERE semifinal.tournament_id = series.tournament_id
            AND semifinal.roster_id = series.roster_id
            AND semifinal.series_id = series.id

        UNION ALL

        SELECT 'final'::TEXT,
            NULL::SMALLINT,
            0,
            final_stage.created_at,
            final_stage.command_id
        FROM tournament_stage_playoff_finals AS final_stage
        WHERE final_stage.tournament_id = series.tournament_id
            AND final_stage.roster_id = series.roster_id
            AND final_stage.final_series_id = series.id
    ) AS stage
    ORDER BY stage.stage_rank,
        stage.round_number DESC NULLS LAST,
        stage.evidence_at DESC,
        stage.evidence_id DESC
    LIMIT 1
) AS series_stage ON TRUE
LEFT JOIN LATERAL (
    SELECT slot.slot_number AS current_game_position,
        slot.category::TEXT AS current_game_category,
        attempt.id AS current_game_attempt_id,
        attempt.state::TEXT AS current_game_state,
        attempt.started_at AS current_game_started_at,
        CASE
            WHEN attempt.state <> 'active' THEN NULL::TIMESTAMPTZ
            WHEN EXISTS (
                SELECT 1
                FROM pauses AS pause
                WHERE pause.tournament_id = series.tournament_id
                    AND pause.roster_id = series.roster_id
                    AND pause.state = 'active'
                    AND (
                        pause.scope_kind = 'tournament'
                        OR (pause.scope_kind = 'series' AND pause.scope_id = series.id)
                        OR (pause.scope_kind = 'game_attempt' AND pause.scope_id = attempt.id)
                        OR (
                            pause.scope_kind = 'wave'
                            AND EXISTS (
                                SELECT 1
                                FROM wave_series AS paused_wave_series
                                WHERE paused_wave_series.wave_id = pause.scope_id
                                    AND paused_wave_series.series_id = series.id
                                    AND paused_wave_series.roster_id = series.roster_id
                            )
                        )
                    )
            ) THEN NULL::TIMESTAMPTZ
            WHEN latest_clock.resumed_deadline IS NOT NULL THEN latest_clock.resumed_deadline
            WHEN attempt.started_at IS NOT NULL THEN attempt.started_at + INTERVAL '180 seconds'
            ELSE NULL::TIMESTAMPTZ
        END AS current_game_effective_deadline,
        attempt.finished_at AS current_game_finished_at,
        attempt.result_reason::TEXT AS current_game_result_reason,
        winner_player.username AS current_game_winner_display_name,
        first_presence.state::TEXT AS first_connection_status,
        second_presence.state::TEXT AS second_connection_status
    FROM game_slots AS slot
    JOIN game_attempts AS attempt
        ON attempt.slot_id = slot.id
        AND attempt.series_id = slot.series_id
        AND attempt.roster_id = slot.roster_id
    LEFT JOIN LATERAL (
        SELECT clock.resumed_deadline
        FROM pause_clocks AS clock
        WHERE clock.game_attempt_id = attempt.id
            AND clock.resumed_deadline IS NOT NULL
        ORDER BY clock.updated_at DESC,
            clock.pause_id DESC
        LIMIT 1
    ) AS latest_clock ON TRUE
    LEFT JOIN participants AS winner
        ON winner.id = attempt.winner_id
        AND winner.roster_id = series.roster_id
    LEFT JOIN players AS winner_player ON winner_player.id = winner.player_id
    LEFT JOIN presence_states AS first_presence
        ON first_presence.tournament_id = series.tournament_id
        AND first_presence.roster_id = series.roster_id
        AND first_presence.series_id = series.id
        AND first_presence.participant_id = series.first_participant_id
    LEFT JOIN presence_states AS second_presence
        ON second_presence.tournament_id = series.tournament_id
        AND second_presence.roster_id = series.roster_id
        AND second_presence.series_id = series.id
        AND second_presence.participant_id = series.second_participant_id
    WHERE slot.series_id = series.id
        AND slot.roster_id = series.roster_id
    ORDER BY attempt.created_at DESC,
        attempt.attempt_number DESC,
        attempt.id DESC
    LIMIT 1
) AS current_game ON TRUE
LEFT JOIN LATERAL (
    SELECT submission.received_at AS submission_received_at
    FROM game_attempts AS attempt
    JOIN official_result_heads AS result_head
        ON result_head.entity_kind = 'game_attempt'
        AND result_head.entity_id = attempt.id
        AND result_head.series_id = attempt.series_id
        AND result_head.roster_id = attempt.roster_id
        AND result_head.game_attempt_id = attempt.id
    JOIN official_result_revisions AS result_revision
        ON result_revision.id = result_head.current_revision_id
        AND result_revision.tournament_id = series.tournament_id
        AND result_revision.entity_kind = 'game_attempt'
        AND result_revision.entity_id = attempt.id
        AND result_revision.game_attempt_id = attempt.id
        AND result_revision.series_id = attempt.series_id
        AND result_revision.roster_id = attempt.roster_id
        AND result_revision.result_state = 'completed'
        AND result_revision.result_reason = 'solved'
        AND result_revision.winner_id = attempt.winner_id
    JOIN result_events AS result_event
        ON result_event.id = result_revision.result_event_id
        AND result_event.tournament_id = result_revision.tournament_id
        AND result_event.roster_id = result_revision.roster_id
        AND result_event.series_id = result_revision.series_id
        AND result_event.attempt_id = attempt.id
        AND result_event.result_state = 'completed'
        AND result_event.result_reason = 'solved'
    JOIN submission_events AS submission
        ON submission.id = result_event.submission_event_id
        AND submission.tournament_id = series.tournament_id
        AND submission.roster_id = attempt.roster_id
        AND submission.series_id = attempt.series_id
        AND submission.attempt_id = attempt.id
        AND submission.participant_id = result_revision.winner_id
        AND submission.status = 'accepted'
    WHERE attempt.id = current_game.current_game_attempt_id
        AND attempt.state = 'completed'
        AND attempt.result_reason = 'solved'
        AND attempt.winner_id IS NOT NULL
        AND attempt.started_at IS NOT NULL
        AND submission.received_at >= attempt.started_at
    ORDER BY submission.received_at,
        submission.id
    LIMIT 1
) AS current_game_solve ON TRUE
WHERE series.tournament_id = $1
    AND series.state <> 'superseded'
ORDER BY series.created_at,
    series.id
`

